/// The Ctrl+V paste flow at the model level (issue #276): a wired reader
/// turns the keystroke into a chip, failures print their named reason,
/// slash/bang submits keep the chips while plain submits consume them and
/// hand the images to the host callback.
library;

import 'package:dart_tui/dart_tui.dart';

import 'package:flutter_agent_harness/src/cli/fa_tui.dart';
import 'package:flutter_agent_harness/src/cli/paste_image.dart';
import 'package:flutter_agent_harness/src/cli/tui_prompt.dart';
import 'package:test/test.dart';

/// A PNG signature plus a payload — sniffable, under every cap.
final _png = <int>[
  0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A, //
  0x00, 0x00, 0x01, 0x02,
];

/// Not an image under any magic the sniffer knows.
final _garbage = <int>[1, 2, 3, 4, 5, 6, 7, 8];

FaTuiModel build({
  Future<PasteboardRead> Function()? reader,
  void Function(String line, List<TuiImageAttachment> images)? onSubmit,
  List<TuiImageAttachment> attachments = const [],
  String inputText = 'hello',
  DateTime Function()? now,
}) {
  return FaTuiModel(
    callbacks: FaTuiCallbacks(
      onSubmit: (line, {images = const []}) async =>
          onSubmit?.call(line, images),
      onSteer: (messages, {images}) async {},
      onModelSelected: (_) async {},
      buildSlashMenu: (_) => const [],
      buildModelMenu: (_, _) => const [],
      statusLine: () => 'test',
      prompt: 'fa> ',
      readClipboardImage: reader,
    ),
    isExited: () => false,
    termHeight: 12,
    now: now,
  ).copyWith(attachments: attachments, inputText: inputText);
}

void main() {
  test('ctrl+v with a wired reader attaches a chip', () async {
    var model = build(reader: () async => PasteboardImage(_png));
    final (next, cmd) = model.update(
      KeyPressMsg(
        const TeaKey(code: KeyCode.rune, text: 'v', modifiers: {KeyMod.ctrl}),
      ),
    );
    model = next as FaTuiModel;
    // The keystroke produced the async read; its result message carries
    // the image into a chip.
    final followUp = await cmd?.call();
    if (followUp != null) {
      model = model.update(followUp).$1 as FaTuiModel;
    }

    expect(model.attachments, hasLength(1));
    expect(model.attachments.first.chip, '[image: clipboard-1.png 12B]');
    expect(model.view().content, contains('[image: clipboard-1.png 12B]'));
  });

  test('an unavailable pasteboard prints its named reason', () async {
    var model = build(
      reader: () async =>
          const PasteboardUnavailable('no pasteboard on this host'),
    );
    final (next, cmd) = model.update(
      KeyPressMsg(
        const TeaKey(code: KeyCode.rune, text: 'v', modifiers: {KeyMod.ctrl}),
      ),
    );
    model = next as FaTuiModel;
    final followUp = await cmd?.call();
    if (followUp != null) {
      model = model.update(followUp).$1 as FaTuiModel;
    }

    expect(model.attachments, isEmpty);
    expect(
      model.outputLines.join('\n'),
      contains('no pasteboard on this host'),
    );
  });

  test('non-image clipboard bytes print the named error', () async {
    var model = build(reader: () async => PasteboardImage(_garbage));
    final (next, cmd) = model.update(
      KeyPressMsg(
        const TeaKey(code: KeyCode.rune, text: 'v', modifiers: {KeyMod.ctrl}),
      ),
    );
    model = next as FaTuiModel;
    final followUp = await cmd?.call();
    if (followUp != null) {
      model = model.update(followUp).$1 as FaTuiModel;
    }

    expect(model.outputLines.join('\n'), contains('magic bytes'));
  });

  test('ctrl+v without a reader prints the unavailable hint', () async {
    var model = build();
    final (next, cmd) = model.update(
      KeyPressMsg(
        const TeaKey(code: KeyCode.rune, text: 'v', modifiers: {KeyMod.ctrl}),
      ),
    );
    model = next as FaTuiModel;
    expect(cmd, isNull, reason: 'no reader: a synchronous note, no work');
    expect(model.attachments, isEmpty);
    expect(model.outputLines.join('\n'), contains('clipboard'));
  });

  test('a plain submit consumes the chips and passes them to the host',
      () async {
    final submitted = <(String, List<TuiImageAttachment>)>[];
    var model = build(
      attachments: [
        TuiImageAttachment(
          name: 'clipboard-1.png',
          mimeType: 'image/png',
          bytes: _png,
        ),
      ],
      onSubmit: (line, images) => submitted.add((line, images)),
    );
    final (next, cmd) = model.update(KeyPressMsg(const TeaKey(code: KeyCode.enter)));
    model = next as FaTuiModel;

    expect(model.attachments, isEmpty, reason: 'chips are consumed');
    await cmd?.call();
    expect(submitted, hasLength(1));
    expect(submitted.single.$1, 'hello');
    expect(submitted.single.$2, hasLength(1));
  });

  test('a slash submit keeps the chips for the next message', () {
    var model = build(
      attachments: [
        TuiImageAttachment(
          name: 'clipboard-1.png',
          mimeType: 'image/png',
          bytes: _png,
        ),
      ],
      inputText: '/help',
    );
    final (next, cmd) = model.update(KeyPressMsg(const TeaKey(code: KeyCode.enter)));
    model = next as FaTuiModel;

    expect(model.attachments, hasLength(1), reason: 'slash keeps chips (E2)');
  });

  test('a theme swap repaints without losing composer state', () {
    var model = build();
    model = model.update(const ThemeSwappedMsg()).$1 as FaTuiModel;
    expect(model.inputText, 'hello');
    expect(model.view().content, contains('hello'));
  });

  // --- Issue #1067: any paste action probes the clipboard for images ---

  test('an empty bracketed paste with a clipboard image attaches a chip',
      () async {
    var model = build(reader: () async => PasteboardImage(_png), inputText: '');
    final (next, cmd) = model.update(PasteMsg(''));
    model = next as FaTuiModel;
    expect(cmd, isNotNull, reason: 'the paste fires the clipboard probe');
    final followUp = await cmd?.call();
    model = model.update(followUp!).$1 as FaTuiModel;

    expect(model.attachments, hasLength(1));
    expect(model.attachments.first.chip, '[image: clipboard-1.png 12B]');
  });

  test('a text bracketed paste inserts the text AND attaches the image',
      () async {
    var model = build(reader: () async => PasteboardImage(_png), inputText: '');
    final (next, cmd) = model.update(PasteMsg('pasted text'));
    model = next as FaTuiModel;
    expect(model.inputText, 'pasted text',
        reason: 'text insertion is unchanged');
    final followUp = await cmd?.call();
    model = model.update(followUp!).$1 as FaTuiModel;

    expect(model.inputText, 'pasted text', reason: 'attach is additive');
    expect(model.attachments, hasLength(1));
  });

  test('a bracketed paste without an image stays silent — no chip, no note',
      () async {
    var model = build(
      reader: () async =>
          const PasteboardUnavailable('no pasteboard on this host'),
      inputText: '',
    );
    final linesBefore = model.outputLines.length;
    final (next, cmd) = model.update(PasteMsg('plain words'));
    model = next as FaTuiModel;
    final followUp = await cmd?.call();
    model = model.update(followUp!).$1 as FaTuiModel;

    expect(model.inputText, 'plain words');
    expect(model.attachments, isEmpty);
    expect(model.outputLines.length, linesBefore,
        reason: 'failed probes never print on a normal text paste');
  });

  test('a bracketed paste without a wired reader inserts text, no probe', () {
    var model = build(inputText: '');
    final (next, cmd) = model.update(PasteMsg('plain words'));
    model = next as FaTuiModel;

    expect(cmd, isNull);
    expect(model.inputText, 'plain words');
  });

  test('prompt mode never probes — pastes stay plain text (AC4)', () {
    var model = build(reader: () async => PasteboardImage(_png)).copyWith(
      prompt: TuiPromptState(TextPromptSpec(question: 'Pick')),
    );
    final (next, cmd) = model.update(PasteMsg('secret-key'));
    model = next as FaTuiModel;

    expect(cmd, isNull, reason: 'no clipboard probe in prompt mode');
    expect(model.prompt, isNotNull, reason: 'paste went to the prompt buffer');
    expect(model.attachments, isEmpty);
  }…

Now I understand the test patterns. Let me analyze the two-part bug:

**Part 1: macOS TIFF-only pasteboard reports no image.**
`_readMacos` only tries `«class PNGf»` and `«class JPEG»`. Fix: add a fallback `«class TIFF»` read, then convert TIFF to PNG via `sips -s format png <in> --out <out>`, and return as `PasteboardImage`. If the conversion fails, fall through to `PasteboardUnavailable`.

**Part 2: UX gap — Ctrl+V with a TEXT clipboard does nothing useful.**
`_handlePasteImageKey` fires the image probe and, on failure, prints the reason. The ticket says: "On probe failure with a text clipboard, Ctrl+V should insert the clipboard text (via `pbpaste` / the platform reader) into the composer."

So we need:
1. A "read clipboard text" function in `clipboard_reader.dart` — e.g. `readPasteboardText()` — using `pbpaste` on macOS, `xclip -selection clipboard -o` / `wl-paste` on Linux, `powershell Get-Clipboard` on Windows. With the injectable `ProcessRunner` seam.
2. Wire a `readClipboardText` callback in `FaTuiCallbacks` and `agent_cli_repl_boot.dart`.
3. In `_handlePasteboardResult` (or `_handlePasteImageKey`), when the probe fails AND there's text available, insert the text into the composer.

Let me think about the design carefully.

For part 2, the flow currently is:
- `_handlePasteImageKey` → `_firePasteboardProbe(reader, silentFailure: false)` → Cmd that returns `PasteboardResultMsg(read, silentFailure: false)`.
- `_handlePasteboardResult` → on `!read is PasteboardImage` and `!silentFailure` → prints the reason.

The desired new behavior: on probe failure (non-image result) from Ctrl+V, try to read the clipboard TEXT; if there's text, insert it into the composer; otherwise print the named reason as before.

Also what about the bracketed-paste image-intent path (empty payload)? The ticket focuses on Ctrl+V: "_handlePasteImageKey returns after the probe". "On probe failure with a text clipboard, Ctrl+V should insert the clipboard text". Let me focus on Ctrl+V primarily. For the empty-payload bracketed paste (image intent), should we also fall back to text? Hmm — the ticket says "Ctrl+V with a TEXT clipboard does nothing (only the image probe runs; `_handlePasteImageKey` returns after the probe)". The bracketed-paste path already inserts text (the terminal delivers it), so it doesn't have this gap. For the empty-payload case, the text is unavailable from the paste event itself (that's why the user gets "clipboard holds no image" — nothing was inserted). Falling back to text on the empty-payload path would also be good UX... but let me be careful: the fix instruction says "On probe failure with a text clipboard, Ctrl+V should insert the clipboard text (via `pbpaste` / the platform reader) into the composer."

I'll implement the fallback for both Ctrl+V and the empty-payload image-intent case? Hmm, but minimal fix principle: "Make minimum targeted fix for the root cause ONLY". The ticket has two parts:
1. TIFF fallback in `_readMacos`.
2. Ctrl+V text fallback.

For part 2, I think the cleanest approach:
- Add `readPasteboardText` to `clipboard_reader.dart` (platform glue): `pbpaste` (macOS), `xclip -selection clipboard -o` then `wl-paste --no-newline` (Linux), PowerShell `Get-Clipboard` (Windows). Text mode is fine here since we want a String. But our `ProcessRunner` returns raw bytes for stdout... Actually `ProcessResult.stdout` is dynamic — the test seam can return a String. The default binary runner returns bytes. For text we can utf8-decode the bytes. Let me write `readPasteboardText({ProcessRunner? runner, String? platform})` that decodes stdout as UTF-8 (with allowMalformed maybe), and returns `PasteboardText(text)` or `PasteboardUnavailable`.

Actually, let me keep the result types in `paste_image.dart` (pure) — add `PasteboardText` to the sealed class? The sealed class `PasteboardRead` is in paste_image.dart. Adding a `PasteboardText` subtype is clean: the TUI can then handle it.

Wait, but `PasteboardResultMsg` carries a `PasteboardRead`, and `_handlePasteboardResult` checks `read is! PasteboardImage`. If the reader returns text... Hmm, but the reader wired to `readClipboardImage` is `readPasteboardImage`, which returns image-or-unavailable. I'll add a separate `readClipboardText` callback in `FaTuiCallbacks`:

```dart
final Future<PasteboardRead> Function()? readClipboardText;
```

