        // secret, e.g. via a hostile pasteboard provider).
        final message = UserMessage(
          content: [
            TextContent(text: 'note supersecret9 in the body'),
            ImageContent(
              data: base64Encode(_chip.bytes),
              mimeType: 'image/supersecret9',
            ),
          ],
