  ],
  timestamp: DateTime.utc(2026),
);

int _occurrences(String haystack, String needle) {
  var count = 0;
  for (
    var i = haystack.indexOf(needle);
    i != -1;
    i = haystack.indexOf(needle, i + needle.length)
  ) {
    count++;
  }
  return count;
}

