        '.$ext';
    final script = [
      'set pngData to (the clipboard as $appleClass)',
      'set imgFile to (open for access POSIX file "$target" with write permission)',
      'try',
      'write pngData to imgFile',
      'close access imgFile',
      'on error errStr',
      'try',
      'close access imgFile',
      'end try',
      'error errStr',
      'end try',
