        : () async {
            final read = await reader();
            if (read is PasteboardImage) return read;
            // gh-1575: a TEXT clipboard used to dead-end in the image
            // probe's named reason — read the text and paste it instead.
            final text = await textReader();
            if (text is PasteboardText && text.text.isNotEmpty) {
